class Solution {
  public int minMirrorPairDistance(int[] nums) {
    Map<Long, Integer> lastIndexOfReverse = new HashMap<>();
    int best = Integer.MAX_VALUE;
    for (int j = 0; j < nums.length; j++) {
      Integer i = lastIndexOfReverse.get((long) nums[j]);
      if (i != null) best = Math.min(best, j - i);
      lastIndexOfReverse.put(reverse(nums[j]), j);
    }
    return best == Integer.MAX_VALUE ? -1 : best;
  }

  private long reverse(long x) {
    long r = 0;
    for (; x > 0; x /= 10) r = r * 10 + x % 10;
    return r;
  }
}
